-- biz_data_snapshot: 经营数据快照（教育后勤2025经营数据）
-- 替换旧的简单 biz_data 表，支持层级结构和完整经营指标

DROP TABLE IF EXISTS biz_data;

CREATE TABLE IF NOT EXISTS biz_data_snapshot (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id          uuid,

  -- 期间
  fiscal_year     text NOT NULL,

  -- 组织层级
  node_name       text NOT NULL,
  center          text,
  biz_class       text,
  biz_level1      text,
  org_tag         text,
  node_level      smallint NOT NULL DEFAULT 0,
  parent_name     text,

  -- 营收
  actual_revenue          numeric,
  budget_revenue          numeric,
  revenue_completion_rate numeric,
  revenue_diff            numeric,
  yoy_revenue             numeric,

  -- 毛利
  actual_gross_profit          numeric,
  budget_gross_profit          numeric,
  gross_profit_completion_rate numeric,
  yoy_gross_profit             numeric,

  -- 毛利率
  actual_gross_margin  numeric,
  budget_gross_margin  numeric,
  gross_margin_diff    numeric,
  yoy_gross_margin     numeric,

  -- 人力成本
  actual_labor_cost          numeric,
  budget_labor_cost          numeric,
  labor_cost_completion_rate numeric,
  yoy_labor_cost             numeric,

  -- 其他成本
  actual_other_cost          numeric,
  budget_other_cost          numeric,
  other_cost_completion_rate numeric,
  yoy_other_cost             numeric,

  -- 利润
  actual_profit          numeric,
  budget_profit          numeric,
  profit_completion_rate numeric,
  profit_diff            numeric,
  yoy_profit             numeric,

  -- 利润率
  actual_profit_margin  numeric,
  budget_profit_margin  numeric,
  profit_margin_diff    numeric,
  yoy_profit_margin     numeric,

  -- 人力成本率
  actual_labor_cost_rate          numeric,
  budget_labor_cost_rate          numeric,
  labor_cost_rate_completion      numeric,
  yoy_labor_cost_rate             numeric,

  -- 人数
  actual_headcount   numeric,
  budget_headcount   numeric,
  headcount_diff     numeric,
  yoy_headcount      numeric,

  created_at  timestamptz DEFAULT now(),
  updated_at  timestamptz DEFAULT now()
);

-- 索引
CREATE INDEX idx_biz_snap_year ON biz_data_snapshot(fiscal_year);
CREATE INDEX idx_biz_snap_level ON biz_data_snapshot(node_level);
CREATE INDEX idx_biz_snap_parent ON biz_data_snapshot(parent_name);
CREATE INDEX idx_biz_snap_org ON biz_data_snapshot(org_id);

-- RLS
ALTER TABLE biz_data_snapshot ENABLE ROW LEVEL SECURITY;

CREATE POLICY "anyone can view biz_data_snapshot"
  ON biz_data_snapshot FOR SELECT
  USING (true);

CREATE POLICY "managers can insert biz_data_snapshot"
  ON biz_data_snapshot FOR INSERT
  WITH CHECK (org_id IN (SELECT org_id FROM profiles WHERE id = auth.uid()));

CREATE POLICY "managers can update biz_data_snapshot"
  ON biz_data_snapshot FOR UPDATE
  USING (org_id IN (SELECT org_id FROM profiles WHERE id = auth.uid()));

